package io.github.describeadmin.codegen.model;

import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;

class FieldTypeMutaGate1Test {

    @Test
    void allKeysReturnsKeysInDeclarationOrder() {
        List<String> expected = List.of(
                "string", "text", "int", "long", "decimal", "flag", "date", "datetime");
        assertEquals(expected, FieldType.allKeys());
    }
}

package io.github.describeadmin.codegen.model;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.lang.reflect.Field;
import org.junit.jupiter.api.Test;

class FieldTypeMutaGate2Test {

    @Test
    void javaSimpleTypeStripsLeadingDotAtIndexZero() throws Exception {
        Field f = FieldType.class.getDeclaredField("javaType");
        f.setAccessible(true);
        FieldType type = FieldType.DATE;
        Object original = f.get(type);
        try {
            f.set(type, ".Foo");
            assertEquals("Foo", type.javaSimpleType());
        } finally {
            f.set(type, original);
        }
        assertEquals("LocalDate", type.javaSimpleType());
    }
}

package io.github.describeadmin.codegen.model;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.List;
import org.junit.jupiter.api.Test;

class FieldTypeMutaGate3Test {

    @Test
    void keyAndAllKeysReturnYamlIdentifiers() {
        assertEquals("string", FieldType.STRING.key());
        assertEquals("text", FieldType.TEXT.key());
        assertEquals("int", FieldType.INT.key());
        assertEquals("long", FieldType.LONG.key());
        assertEquals("decimal", FieldType.DECIMAL.key());
        assertEquals("flag", FieldType.FLAG.key());
        assertEquals("date", FieldType.DATE.key());
        assertEquals("datetime", FieldType.DATETIME.key());
        assertEquals(
                List.of("string", "text", "int", "long", "decimal", "flag", "date", "datetime"),
                FieldType.allKeys());
    }
}

package io.github.describeadmin.codegen.model;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class FieldTypeMutaGate4Test {

    @Test
    void needsLengthIsTrueOnlyForString() {
        assertTrue(FieldType.STRING.needsLength());
        for (FieldType type : FieldType.values()) {
            if (type != FieldType.STRING) {
                assertFalse(type.needsLength(), type.name());
            }
        }
    }
}

package io.github.describeadmin.codegen.model;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class FieldTypeMutaGate5Test {

    @Test
    void needsPrecisionOnlyForDecimal() {
        assertTrue(FieldType.DECIMAL.needsPrecision());
        for (FieldType type : FieldType.values()) {
            if (type != FieldType.DECIMAL) {
                assertFalse(type.needsPrecision(), type + " should not need precision");
            }
        }
        assertEquals(false, FieldType.STRING.needsPrecision());
    }
}

